CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT DEFAULT 'd', c1  NOT NULL DEFAULT 0, c2 INT, c3 NUMERIC DEFAULT 'd', c4 NUMERIC DEFAULT 'd');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(5, 0, 5, x'c7', -110);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1 INTEGER, c2 TEXT COLLATE NOCASE, c3 TEXT, c4  CHECK(c4 IS NULL OR length(c4) < 40), ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(NULL, NULL, 355, 276, NULL, 1);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(603.4389, 4, -0.0, 'naïve', 'tau', 1);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(162, NULL, 93, '1e3', 'phi', 4);
SELECT length('naïve'), upper('naïve'), lower('naïve'), substr('naïve', -1, 4), instr('naïve', '0x1F'), replace('naïve', '', ''), trim('naïve'), ltrim('naïve', 'ab'), hex('naïve'), quote('naïve'), unicode('naïve'), 'naïve' LIKE '%a_', 'naïve' GLOB '?', char(71, 686), 'naïve' || '0x1F', 'naïve' < '0x1F', 'naïve' = '0x1F' COLLATE NOCASE;
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', -3, 5), instr('a%b', '1e3'), replace('a%b', 'a', '_'), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '_', 'a%b' GLOB '*[a-m]*', char(82, 942), 'a%b' || '1e3', 'a%b' < '1e3', 'a%b' = '1e3' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', 4, 3), instr('', 'eta'), replace('', 'a', 'XY'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE 'A%', '' GLOB '?', char(67, 572), '' || 'eta', '' < 'eta', '' = 'eta' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 1, 5), instr('sigma', 'zeta'), replace('sigma', 'a', '_'), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '%é%', 'sigma' GLOB 'a*', char(77, 481), 'sigma' || 'zeta', 'sigma' < 'zeta', 'sigma' = 'zeta' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 2, 1), instr('zeta', 'MU'), replace('zeta', '', 'XY'), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE 'A%', 'zeta' GLOB '*[a-m]*', char(90, 685), 'zeta' || 'MU', 'zeta' < 'MU', 'zeta' = 'MU' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -2, 3), instr('it''s', 'chi'), replace('it''s', '', 'XY'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE '_', 'it''s' GLOB 'a*', char(83, 904), 'it''s' || 'chi', 'it''s' < 'chi', 'it''s' = 'chi' COLLATE NOCASE;
SELECT length('NULL'), upper('NULL'), lower('NULL'), substr('NULL', 1, 2), instr('NULL', '42'), replace('NULL', 'e', 'XY'), trim('NULL'), ltrim('NULL', 'ab'), hex('NULL'), quote('NULL'), unicode('NULL'), 'NULL' LIKE 'a%', 'NULL' GLOB '?', char(66, 829), 'NULL' || '42', 'NULL' < '42', 'NULL' = '42' COLLATE NOCASE;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t1.id) FROM t1 ORDER BY c4, id;
SELECT id FROM t1 WHERE id NOT IN (SELECT id FROM t1 WHERE x'1d9ed83198') ORDER BY id;
SELECT id FROM t1 x WHERE EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 0) ORDER BY id;
SELECT c1 FROM t1 UNION SELECT c2 FROM t1 ORDER BY 1 LIMIT 11 OFFSET 2;
CREATE UNIQUE INDEX IF NOT EXISTS i77 ON t1(c4 DESC, id);
SELECT id, c4 FROM t1 WHERE c4 > NULL ORDER BY c4, id;
SELECT count(*) FROM t1 INDEXED BY i77 WHERE c4 IS NOT NULL;
REINDEX t1;
DROP INDEX IF EXISTS i77;
CREATE INDEX IF NOT EXISTS i19 ON t0(c1, id) WHERE c1 IS NOT NULL;
SELECT id, c1 FROM t0 WHERE c1 = -0.0 ORDER BY c1, id;
SELECT count(*) FROM t0 INDEXED BY i19 WHERE c1 IS NOT NULL;
REINDEX t0;
DROP INDEX IF EXISTS i19;
